import Typography from "@mui/material/Typography";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import CustomDataGrid from "src/@core/components/data-grid";
import Chip from "@mui/material/Chip";
import { styled } from "@mui/material/styles";
import { MEDIA_URL } from "src/network/endpoints";
import { useEffect } from "react";
import { useState } from "react";

function TableSuccessStories({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
  status,
}) {
  const statusColors = {
    inactive: "#3A3541AD",
    active: "#66bb6a",
  };
  const CustomChip = styled(Chip)(({ label }) => ({
    backgroundColor: statusColors[label] || statusColors.default,
    textTransform: "capitalize",
    color: "#fff",
    width: "100px",
  }));
  const [activeData, setActiveData] = useState([]);
  const [inActiveData, setInActiveData] = useState([]);
  useEffect(() => {
    const activeRows = rows.filter((row) => row.status === "active");
    setActiveData(activeRows);
    const inActiveRows = rows.filter((row) => row.status === "inactive");
    setInActiveData(inActiveRows);
  }, [rows]);
  const displayedRows =
    status === "active"
      ? activeData
      : status === "inactive"
      ? inActiveData
      : rows;
  return (
    <CustomDataGrid
      loading={loading}
      rowCount={totalCount}
      rows={displayedRows}
      columns={[
        {
          field: "title",
          flex: 0.5,
          minWidth: 200,
          sortable: false,
          headerName: "Title",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.title}>
              {row.title}
            </Typography>
          ),
        },
        {
          field: "logo",
          flex: 0.5,
          minWidth: 150,
          sortable: false,
          headerName: "Logo",
          renderCell: ({ row }) => (
            <img
              alt=""
              src={
                row.logo
                  ? row.logo.startsWith(
                      "https://dwitst24.blob.core.windows.net/upload/"
                    )
                    ? row.logo.replace(
                        "https://dwitst24.blob.core.windows.net/upload/",
                        MEDIA_URL
                      )
                    : row.logo.startsWith("http")
                    ? row.logo
                    : `${MEDIA_URL}${row.logo}`
                  : "" // Fallback in case icon_image is null or empty
              }
              style={{ height: "30px", width: "50px" }}
            />
          ),
        },
        // {
        //   field: "description",
        //   minWidth: 600,
        //   sortable: false,
        //   headerName: "Description",
        //   renderCell: ({ row }) => (
        //     <Typography noWrap variant="body2" title={row.description}>
        //       {row.description}
        //     </Typography>
        //   ),
        // },

        // {
        //   field: "key_words",
        //   minWidth: 300,
        //   flex: 1,
        //   sortable: false,
        //   headerName: "Key Words",

        //   // renderCell: ({ row }) => {
        //   //   row?.key_words?.map((item) => <CustomChip label={item} />);
        //   // },
        //   renderCell: ({ row }) => {
        //     if (Array.isArray(row?.key_words)) {
        //       return row.key_words.map((item, index) => (
        //         <CustomChip key={index} label={item} />
        //       ));
        //     }
        //     return null; // or return some fallback content if key_words is not an array
        //   },
        // },
        {
          field: "status",
          minWidth: 180,
          sortable: false,
          headerName: "Status",
          renderCell: ({ row }) => <CustomChip label={row.status} />,
        },
        {
          field: "Actions",
          flex: 0,
          minWidth: 170,
          sortable: false,
          headerName: "Actions",
          renderCell: ({ row }) => (
            <Box display="flex" alignItems="center" gap="10px">
              <IconButton
                size="small"
                color="primary"
                variant="outlined"
                onClick={(e) => toggleEdit(e, "edit", row)}
              >
                <EditIcon />
              </IconButton>
              <IconButton
                size="small"
                color="secondary"
                onClick={(e) => toggleDelete(e, row)}
              >
                <DeleteIcon />
              </IconButton>
            </Box>
          ),
        },
      ]}
      currentPage={currentPage}
      pageSize={pageSize}
      setCurrentPage={setCurrentPage}
      setPageSize={setPageSize}
    />
  );
}

export default TableSuccessStories;
